content.content:
1	package containers
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/charmbracelet/lipgloss"
8	
9		"github.com/anthnel/devdesk/internal/docker"
10		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
11		"github.com/anthnel/devdesk/internal/ui/datatable"
12		"github.com/anthnel/devdesk/internal/ui/indicator"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// observedState maps what the engine reports for a container onto the shared
17	// activity vocabulary (Rule 125). A running container is Idle: the nominal
18	// state shows the container icon, not a glyph. An exit without a known code is
19	// Failed, so a possible crash is never shown as a clean stop. Engine synonyms
20	// (podman's configured, initialized, stopping...) and anything unknown fall
21	// back to Unknown.
22	func observedState(c docker.Container) indicator.State {
23		switch c.State {
24		case "running":
25			return indicator.Idle
26		case "restarting":
27			return indicator.Restarting
28		case "paused":
29			return indicator.Suspended
30		case "exited", "stopped":
31			if c.Facts.HasExitCode && c.Facts.ExitCode == 0 {
32				return indicator.Skipped
33			}
34			return indicator.Failed
35		case "dead":
36			return indicator.Failed
37		}
38		return indicator.Unknown
39	}
40	
41	// restIcon is what the activity column shows for a container that is Idle.
42	func restIcon(docker.Container) string { return theme.IconContainer }
43	
44	// restStyle colours restIcon with the container role (plain text by default).
45	func restStyle(docker.Container) lipgloss.Style {
46		return theme.IconStyle(theme.IconRoleContainer)
47	}
48	
49	// ActivityTables returns the read-only face of the view's table, keyed by the
50	// name the activity-column guard (internal/app) knows it by.
51	func (m Model) ActivityTables() map[string]datatable.ActivityTable {
52		return map[string]datatable.ActivityTable{"containers": &m.containerTable}
53	}
54	
55	// WantsBlink is the router's BlinkingView hook: true while a row action is in
56	// flight, so the router frames the view for the running dot's blink.
57	func (m Model) WantsBlink() bool { return len(m.containerTable.BusyLabels()) > 0 }
58	
59	// observedText is the footer sentence for a container at rest, without a
60	// glyph: the glyph is added by components.DescribeRow from observedState.
61	func observedText(c docker.Container) string {
62		f := c.Facts
63		ago := ""
64		if f.HasAge {
65			ago = " — " + theme.AgoFor(f.Age)
66		}
67		switch c.State {
68		case "running":
69			if f.HasAge {
70				return "Running since " + theme.AgoFor(f.Age)
71			}
72			return "Running"
73		case "restarting":
74			if f.HasExitCode {
75				return fmt.Sprintf("Restarting — last exit code %d", f.ExitCode)
76			}
77			return "Restarting"
78		case "paused":
79			return "Paused"
80		case "created":
81			return "Created, never started"
82		case "exited", "stopped":
83			switch {
84			case !f.HasExitCode:
85				return "Exited (exit code unknown)"
86			case f.ExitCode == 0:
87				return "Exited cleanly (code 0)" + ago
88			}
89			return fmt.Sprintf("Exited with code %d", f.ExitCode) + ago
90		case "dead":
91			return "Dead — the engine could not stop it cleanly"
92		case "removing":
93			return "Removing"
94		}
95		if c.State == "" {
96			return ""
97		}
98		return strings.ToUpper(c.State[:1]) + c.State[1:]
99	}
100	
101	// selectedDetail is what the footer says about the selected container: the
102	// action running on it, else its observed state in words. Empty when nothing
103	// is selected.
104	func (m Model) selectedDetail() sharedcomponents.RowDetail {
105		c := m.getSelectedContainer()
106		if c == nil {
107			return sharedcomponents.RowDetail{}
108		}
109		if label, ok := m.containerTable.BusyLabel(c.ID); ok {
110			return sharedcomponents.RowDetail{
111				Glyph:  indicator.Glyph(indicator.Running, true), // the footer glyph never blinks
112				Lead:   strings.TrimSuffix(label, c.Name),
113				Target: c.Name,
114			}
115		}
116		return sharedcomponents.DescribeRow(sharedcomponents.RowQuery{
117			Observed: observedState(*c), ObservedText: observedText(*c),
118		}).Detail
119	}
120

